-- 29_philippine_geography.sql
-- The whole country's geography, and the parent links that make Province ->
-- Municipality -> Barangay actually cascade.
--
-- WHY THIS IS A SCHEMA CHANGE AND NOT JUST DATA. `municipalities` and `barangays` were
-- flat (id, name) lookups with UNIQUE(name) and NO link to their parent, so:
--
--   * the cascading pickers could not work at all. The forms join
--     municipalities.province_id and barangays.municipality_id; neither column existed,
--     so every query threw, every catch swallowed it, and choosing a province produced
--     an EMPTY municipality list. The screens looked wired up and did nothing.
--
--   * UNIQUE(name) cannot hold this data. 109 of 1,443 distinct city/municipality names
--     repeat across provinces (there are several San Isidros), and 3,942 of 27,068
--     distinct barangay names repeat - loading the country under UNIQUE(name) would
--     silently collapse 42,029 barangays into 27,068 and file them under whichever
--     municipality happened to be inserted first. Both indexes are replaced by the PSGC
--     code, which is the real key.
--
-- Source: the Philippine Standard Geographic Code as published for address pickers -
-- 87 provinces (incl. the NCR districts, which the PSGC treats as province-level),
-- 1,647 cities and municipalities, 42,029 barangays. `psgc_code` is carried on every
-- row so a later PSGC revision can be re-applied over this one.
--
-- EXISTING ROWS ARE NOT REPLACED. The office already has Cagayan / Penablanca /
-- Tuguegarao City / Parabba / Patagueleg, and `deaths` and `marriages` hold FOREIGN KEYS
-- to those ids - deleting and re-seeding would break them. Instead each existing row is
-- ATTACHED to its PSGC row (accent-insensitively, and only where the country holds
-- EXACTLY ONE place of that name, so a legacy "San Isidro" is never bound to the wrong
-- province), and its own spelling is left alone. That is deliberate: the office's
-- records store place names as TEXT, so silently rewriting "Penablanca" to the PSGC
-- "Penablanca-with-enye" would make the master file disagree with every record that
-- already quotes it. Their data, their call - one UPDATE changes it when they decide.

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP PROCEDURE IF EXISTS _croms_geo_schema;
DELIMITER //
CREATE PROCEDURE _croms_geo_schema()
BEGIN
    -- psgc_code on all three, as the stable natural key.
    IF NOT EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE()
                   AND TABLE_NAME = 'provinces' AND COLUMN_NAME = 'psgc_code') THEN
        ALTER TABLE `provinces` ADD COLUMN `psgc_code` VARCHAR(12) NULL;
        ALTER TABLE `provinces` ADD UNIQUE KEY `uq_provinces_psgc` (`psgc_code`);
    END IF;

    IF NOT EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE()
                   AND TABLE_NAME = 'municipalities' AND COLUMN_NAME = 'psgc_code') THEN
        ALTER TABLE `municipalities` ADD COLUMN `psgc_code` VARCHAR(12) NULL;
        ALTER TABLE `municipalities` ADD UNIQUE KEY `uq_municipalities_psgc` (`psgc_code`);
    END IF;
    -- NULL-able on purpose: LookupStore.Ensure writes a bare name when a scan turns up a
    -- place the master file has not got, and that must keep working. Such a row simply
    -- does not appear under any province until someone files it.
    IF NOT EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE()
                   AND TABLE_NAME = 'municipalities' AND COLUMN_NAME = 'province_id') THEN
        ALTER TABLE `municipalities` ADD COLUMN `province_id` INT NULL AFTER `id`;
        ALTER TABLE `municipalities` ADD INDEX `ix_municipalities_province` (`province_id`, `name`);
    END IF;

    IF NOT EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE()
                   AND TABLE_NAME = 'barangays' AND COLUMN_NAME = 'psgc_code') THEN
        ALTER TABLE `barangays` ADD COLUMN `psgc_code` VARCHAR(12) NULL;
        ALTER TABLE `barangays` ADD UNIQUE KEY `uq_barangays_psgc` (`psgc_code`);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE()
                   AND TABLE_NAME = 'barangays' AND COLUMN_NAME = 'municipality_id') THEN
        ALTER TABLE `barangays` ADD COLUMN `municipality_id` INT NULL AFTER `id`;
        ALTER TABLE `barangays` ADD INDEX `ix_barangays_municipality` (`municipality_id`, `name`);
    END IF;

    -- The two indexes this data cannot live under.
    IF EXISTS (SELECT 1 FROM information_schema.STATISTICS WHERE TABLE_SCHEMA = DATABASE()
               AND TABLE_NAME = 'municipalities' AND INDEX_NAME = 'uq_municipalities_name') THEN
        ALTER TABLE `municipalities` DROP INDEX `uq_municipalities_name`;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.STATISTICS WHERE TABLE_SCHEMA = DATABASE()
               AND TABLE_NAME = 'barangays' AND INDEX_NAME = 'uq_barangays_name') THEN
        ALTER TABLE `barangays` DROP INDEX `uq_barangays_name`;
    END IF;
END //
DELIMITER ;

CALL _croms_geo_schema();
DROP PROCEDURE IF EXISTS _croms_geo_schema;

-- ---------------------------------------------------------------------------
-- Staging. The reference set lands here first so the existing rows can be matched
-- against it before anything is inserted.
--
-- Deliberately NOT temporary tables: MySQL refuses to open a TEMPORARY table twice in
-- one statement (error 1137), and the "is this name unique in the country?" guard below
-- has to read the same staging table in both the join and the subquery. They are dropped
-- at the end of the file.

DROP TABLE IF EXISTS _geo_prov;
DROP TABLE IF EXISTS _geo_city;
DROP TABLE IF EXISTS _geo_brgy;

CREATE TABLE _geo_prov (
  psgc VARCHAR(12) NOT NULL PRIMARY KEY,
  code VARCHAR(12) NOT NULL,
  name VARCHAR(100) NOT NULL,
  KEY (code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE _geo_city (
  psgc VARCHAR(12) NOT NULL PRIMARY KEY,
  code VARCHAR(12) NOT NULL,
  prov VARCHAR(12) NOT NULL,
  name VARCHAR(100) NOT NULL,
  KEY (code), KEY (prov)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE _geo_brgy (
  psgc VARCHAR(12) NOT NULL PRIMARY KEY,
  city VARCHAR(12) NOT NULL,
  name VARCHAR(100) NOT NULL,
  KEY (city)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- 87 provinces (PSGC province-level units, NCR districts included).

-- 1,647 cities and municipalities.

-- 42,029 barangays.

-- ---------------------------------------------------------------------------
-- 0a. Strip the "(Capital)" annotation from any row an earlier run of this migration
--     inserted with it. It is a PSGC note, not part of the name, and while it is there
--     the office's own "Tuguegarao City" cannot be recognised as the same place.

UPDATE municipalities SET name = TRIM(REPLACE(name, ' (Capital)', ''))
WHERE name LIKE '% (Capital)';

-- 0b. Merge a legacy row into its reference twin, where a previous run of this
--    migration already inserted one. Without this the attach below would try to give
--    the legacy row a psgc_code the twin already holds and fail on the unique key.
--    The foreign keys in `deaths` and `marriages` are repointed at the survivor FIRST,
--    so nothing is orphaned; the legacy row is only then removed.

UPDATE deaths d
JOIN provinces l ON l.id = d.province_id AND l.psgc_code IS NULL
JOIN provinces k ON k.psgc_code IS NOT NULL
 AND k.name COLLATE utf8mb4_0900_ai_ci = l.name COLLATE utf8mb4_0900_ai_ci
SET d.province_id = k.id;
UPDATE marriages m
JOIN provinces l ON l.id = m.place_province_id AND l.psgc_code IS NULL
JOIN provinces k ON k.psgc_code IS NOT NULL
 AND k.name COLLATE utf8mb4_0900_ai_ci = l.name COLLATE utf8mb4_0900_ai_ci
SET m.place_province_id = k.id;
DELETE l FROM provinces l
JOIN provinces k ON k.psgc_code IS NOT NULL
 AND k.name COLLATE utf8mb4_0900_ai_ci = l.name COLLATE utf8mb4_0900_ai_ci
WHERE l.psgc_code IS NULL;

UPDATE deaths d
JOIN municipalities l ON l.id = d.municipality_id AND l.psgc_code IS NULL
JOIN municipalities k ON k.psgc_code IS NOT NULL
 AND k.name COLLATE utf8mb4_0900_ai_ci = l.name COLLATE utf8mb4_0900_ai_ci
SET d.municipality_id = k.id;
UPDATE marriages m
JOIN municipalities l ON l.id = m.place_municipality_id AND l.psgc_code IS NULL
JOIN municipalities k ON k.psgc_code IS NOT NULL
 AND k.name COLLATE utf8mb4_0900_ai_ci = l.name COLLATE utf8mb4_0900_ai_ci
SET m.place_municipality_id = k.id;
DELETE l FROM municipalities l
JOIN municipalities k ON k.psgc_code IS NOT NULL
 AND k.name COLLATE utf8mb4_0900_ai_ci = l.name COLLATE utf8mb4_0900_ai_ci
WHERE l.psgc_code IS NULL
  AND (SELECT COUNT(*) FROM _geo_city x
       WHERE x.name COLLATE utf8mb4_0900_ai_ci = l.name COLLATE utf8mb4_0900_ai_ci) = 1;

DELETE l FROM barangays l
JOIN barangays k ON k.psgc_code IS NOT NULL
 AND k.name COLLATE utf8mb4_0900_ai_ci = l.name COLLATE utf8mb4_0900_ai_ci
WHERE l.psgc_code IS NULL
  AND (SELECT COUNT(*) FROM _geo_brgy x
       WHERE x.name COLLATE utf8mb4_0900_ai_ci = l.name COLLATE utf8mb4_0900_ai_ci) = 1;

-- 1. Attach what the office already has, so its ids (and the foreign keys in
--    `deaths` and `marriages`) survive. utf8mb4_0900_ai_ci is accent-insensitive, so
--    "Penablanca" finds the enye spelling. The "exactly one" guard is what stops a
--    legacy "San Isidro" being bound to an arbitrary one of the several that exist.

UPDATE provinces p
JOIN _geo_prov g
  ON g.name COLLATE utf8mb4_0900_ai_ci = p.name COLLATE utf8mb4_0900_ai_ci
SET p.psgc_code = g.psgc
WHERE p.psgc_code IS NULL;

UPDATE municipalities m
JOIN _geo_city g
  ON g.name COLLATE utf8mb4_0900_ai_ci = m.name COLLATE utf8mb4_0900_ai_ci
SET m.psgc_code = g.psgc
WHERE m.psgc_code IS NULL
  AND (SELECT COUNT(*) FROM _geo_city x
       WHERE x.name COLLATE utf8mb4_0900_ai_ci = m.name COLLATE utf8mb4_0900_ai_ci) = 1;

UPDATE barangays b
JOIN _geo_brgy g
  ON g.name COLLATE utf8mb4_0900_ai_ci = b.name COLLATE utf8mb4_0900_ai_ci
SET b.psgc_code = g.psgc
WHERE b.psgc_code IS NULL
  AND (SELECT COUNT(*) FROM _geo_brgy x
       WHERE x.name COLLATE utf8mb4_0900_ai_ci = b.name COLLATE utf8mb4_0900_ai_ci) = 1;

-- 2. Insert everything the office does not have yet. Re-running the migration adds
--    only what a newer PSGC revision introduced.

SELECT g.psgc, g.name FROM _geo_prov g
LEFT JOIN provinces p ON p.psgc_code = g.psgc
WHERE p.id IS NULL;

SELECT g.psgc, p.id, g.name
FROM _geo_city g
JOIN _geo_prov gp ON gp.code = g.prov
JOIN provinces p ON p.psgc_code = gp.psgc
LEFT JOIN municipalities m ON m.psgc_code = g.psgc
WHERE m.id IS NULL;

SELECT g.psgc, m.id, g.name
FROM _geo_brgy g
JOIN _geo_city gc ON gc.code = g.city
JOIN municipalities m ON m.psgc_code = gc.psgc
LEFT JOIN barangays b ON b.psgc_code = g.psgc
WHERE b.id IS NULL;

-- 3. Give the attached legacy rows their parent link. They were matched by name in
--    step 1 but still carry no province/municipality, which is what the cascade reads.

UPDATE municipalities m
JOIN _geo_city g ON g.psgc = m.psgc_code
JOIN _geo_prov gp ON gp.code = g.prov
JOIN provinces p ON p.psgc_code = gp.psgc
SET m.province_id = p.id
WHERE m.province_id IS NULL;

UPDATE barangays b
JOIN _geo_brgy g ON g.psgc = b.psgc_code
JOIN _geo_city gc ON gc.code = g.city
JOIN municipalities m ON m.psgc_code = gc.psgc
SET b.municipality_id = m.id
WHERE b.municipality_id IS NULL;

DROP TABLE IF EXISTS _geo_prov;
DROP TABLE IF EXISTS _geo_city;
DROP TABLE IF EXISTS _geo_brgy;

SET FOREIGN_KEY_CHECKS = 1;

